#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;long long k,x,y;if(!(cin>>n>>m>>k))return 0;cin>>x>>y;vector<long long>a(n),b(m);for(auto&v:a)cin>>v;for(auto&v:b)cin>>v;sort(a.begin(),a.end());sort(b.begin(),b.end());vector<long long> pa(n+1),pb(m+1),pc(m+1);for(int i=0;i<n;i++)pa[i+1]=pa[i]+a[i];for(int i=0;i<m;i++){pb[i+1]=pb[i]+b[i];pc[i+1]=pc[i]+(b[i]+k-1)/k;}int ans=0;long long budget=x+k*y;for(int d=0;d<=m && pc[d]<=y;d++){long long rem=budget-pb[d];if(rem<0)continue;int q=upper_bound(pa.begin(),pa.end(),rem)-pa.begin()-1;ans=max(ans,d+q);}cout<<ans<<'\n';}
